import{_ as t,o as i,c as a,a3 as o}from"./chunks/framework.1Y430-yj.js";const m=JSON.parse('{"title":"Exploring Practical Mixed-Recipe Reactor Crucibles (Abandoned)","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"反应池混用实用可能性探究（已被抛弃）","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=rJRctcbf03vvLbgMp7b1iL","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-rJRctcbf03vvLbgMp7b1iL.md","filePath":"logistics/src/page-rJRctcbf03vvLbgMp7b1iL.md","lastUpdated":null}'),n={name:"logistics/src/page-rJRctcbf03vvLbgMp7b1iL.md"};function s(r,e,c,p,l,u){return i(),a("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="反应池混用实用可能性探究-已被抛弃" aria-hidden="true"></span><h1 id="exploring-practical-mixed-recipe-reactor-crucibles-abandoned" tabindex="-1">Exploring Practical Mixed-Recipe Reactor Crucibles (Abandoned) <a class="header-anchor" href="#exploring-practical-mixed-recipe-reactor-crucibles-abandoned" aria-label="Permalink to &quot;Exploring Practical Mixed-Recipe Reactor Crucibles (Abandoned)&quot;">​</a></h1><blockquote><p>Source page ID: <code>rJRctcbf03vvLbgMp7b1iL</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=rJRctcbf03vvLbgMp7b1iL" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><details><summary>Chat log 1</summary><p>xyIvneu_:</p><p>Give me an answer: can the crucible be compressed? If not, what is the difficulty?</p><p>?caution?caution?:</p><p>Let me reproduce that bug.</p><p>It can be compressed, but the state feels extremely fragile.</p><p>@xyIvneu_ This is the situation.</p><p>I will upload the video again. You cannot guarantee it will not block.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-5eca694d45e1e92e.jpeg" alt="Exploring Practical Mixed-Recipe Reactor Crucibles (Abandoned)"></p><p>Producing both effluents.</p><p>The two recipes cannot share a cycle.</p><p>Once one recipe blocks, the crucible stops operating.</p><p>Cipolla_:</p><p>Looks risky.</p><p>c:</p><p>So do they react simultaneously?</p><p>Isn&#39;t that just like a stash? Two items enter; if one item&#39;s depot storage fills, the other blocks too.</p><p>?caution?caution?:</p><p>They must react simultaneously, surely.</p><p>Reply to xyIvneu_: Give me an answer: can the crucible be compressed? If not, what is the difficulty?</p><p>@xyIvneu_ The difficulty is guaranteeing that water and Sewage do not accumulate.</p><p>madSUN:</p><p>Can someone describe the crucible&#39;s current behavior?</p><p>Isn&#39;t it impossible to run several reactions simultaneously?</p><p>?caution?caution?:</p><p>Deadlock cannot be avoided.</p><p>madSUN:</p><p>I do not understand which step fails: are multiple reactions inherently unable to run simultaneously, or do they jam afterward?</p><p>?caution?caution?:</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-565ac0edf18d7277.jpeg" alt="Exploring Practical Mixed-Recipe Reactor Crucibles (Abandoned)"></p><p>Only 5 slots, but 6 materials must coexist.</p><p>If one reaction jams, the entire crucible jams.</p><p>One reaction cannot fail to complete while another continues.</p><p>It seems that even if reaction B could free reaction A from a jam, once the jam occurs the machine stops, preventing B too.</p></details><p>Chat-log-1 AI summary: The crucible cannot be compressed because of deadlock risk. The two recipes cannot share a cycle, 5 slots must hold 6 materials, and one jammed reaction stops the entire crucible, preventing another reaction from rescuing it.</p><details><summary>Experimental result 1</summary><p>Clean Water<em>50 + effluent</em>50 + Liquid Xiranite<em>50 + placeholder A</em>0 + placeholder B*0 → blocked.</p><p>...</p></details><details><summary>Chat log 2</summary><p>xyIvneu_</p><p>Tried it: completely unworkable. Crucible magic is bankrupt for now.</p><p>苍孤狼</p><p>What exactly are you testing?</p><p>A double-speed crucible solution recipe?</p><p>xyIvneu_</p><p>I cannot understand why Jincao and Yazhen entering together occupy only one slot,</p><p>yet water and Sewage entering together block.</p><p>I can only suspect they internally optimized the Jincao/Yazhen lines.</p><p>madSUN</p><p>Reply to xyIvneu_: I cannot understand why Jincao and Yazhen entering together occupy only one slot.</p><p>Could liquids and belts use different processing logic?</p><p>Try Jincao + Xiranite, for example.</p><p>xyIvneu_</p><p>Reply to madSUN: Try Jincao + Xiranite, for example.</p><p>Only one slot.</p><p>Reply to madSUN: Could liquids and belts use different processing logic?</p><p>I suspect that too, but it is unfalsifiable.</p><p>苍孤狼</p><p>Two different solids can enter at full rate and share one slot?</p><p>Unfortunately the Liquid Xiranite-to-Xircon-Effluent recipe involves 4 different liquids, so it cannot combine with another recipe.</p><p>Xircon synthesis plus Liquid Xiranite synthesis: liquids: water, Xircon Effluent, Sewage, Liquid Xiranite; solids: inputs Ferrium Powder and Xiranite, output Xircon. Liquids occupy 4 slots, both solid inputs share 1, and Xircon takes 1: still 6, over the limit.</p><p>Solid output is instantaneous; if those three solids shared one slot, the recipes could combine.</p></details><details><summary>Experimental result</summary><p>When a reaction reduces an input&#39;s inventory to zero and an external new item is waiting, the crucible “may” stop that item entering, or may not.</p></details><p>Mechanism hypotheses were merged into the crucible-behavior survey; crucible optimization was merged into version-progression planning.</p></div>',1)])])}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
